import { createSignal } from "solid-js";
const [count] = createSignal(0);
const [label] = createSignal("world");
export const Concat = () => <div>{"hello " + label}</div>;
export const Unary = () => <div>{!count ? "empty" : "full"}</div>;
export const Template = () => <div>{`count is ${count}`}</div>;
export const Hyphenated = () => <div data-count={count} />;

import { createSignal } from "solid-js";
export function Comp() {
  const [count] = createSignal(0);
  const value = count();
  return <div>{value}</div>;
}

import { createStore } from "solid-js";
const [profile] = createStore({ count: 0, user: { name: "Ada" } });
// The readonly-ness is shallow.
export function Nested() {
  profile.user.name = "Grace";
}
// A cast erases it from a root property too.
export function Cast() {
  (profile as { count: number }).count = 1;
}
// A props member is not readonly at all.
export function Props(props: { n: number }) {
  props.n = 1;
}

export function Child(props: { state: { count: number } }) {
  return <button onClick={() => { props.state.count++; }}>{props.state.count}</button>;
}
export function Wrapped(props: { state: { count: number } }) {
  return <button onClick={() => { (props.state as { count: number }).count = 2; }}>{props.state.count}</button>;
}
export function App() {
  const state = { count: 0 };
  return <div><Child state={state} /><Wrapped state={state} /></div>;
}

import { createSignal, createMemo } from "solid-js";
const [count, setCount] = createSignal(0);
export const doubled = createMemo(() => {
  setCount(1);
  return count();
});

export function Row(props: { name: string }) {
  const { name } = props;
  return <div>{name}</div>;
}

import { createSignal } from "solid-js";
const [ready] = createSignal(false);
export function Gate() {
  if (ready()) return <div>on</div>;
  return <span>off</span>;
}

interface Rows extends Array<string> { map(callback: (item: string) => string): string[]; }
declare const rows: Rows;
const [items] = createSignal(rows);
export const App = () => <ul>{items().map((item) => item)}</ul>;

