import { createMemo, createSignal, resolve } from "solid-js";

const [user] = createSignal("ada");

export function InMemoCompute() {
  const label = createMemo(() => {
    void resolve(() => user());
    return user();
  });
  return <div>{String(label())}</div>;
}

import { createMemo, createSignal, resolve, untrack } from "solid-js";

const [user] = createSignal("ada");

export function UntrackedResolve() {
  const label = createMemo(() => {
    untrack(() => {
      void resolve(() => user());
    });
    return user();
  });
  return <div>{String(label())}</div>;
}

